<?php
require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../helpers/auth.php'; require_once __DIR__ . '/../helpers/escape.php'; require_admin();
$pageTitle='Pengguna';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'staff');$fullName=trim((string)($_POST['full_name']??''));if(!preg_match('/^[a-zA-Z0-9_.-]{3,50}$/',$username)||strlen($password)<8||$fullName===''||!in_array($role,['admin','staff'],true))$error='Username 3–50 karakter, nama wajib diisi, password minimal 8 karakter, dan role harus valid.';else{try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO users(username,password_hash,role) VALUES(:u,:p,:r)');$s->execute(['u'=>$username,'p'=>password_hash($password,PASSWORD_DEFAULT),'r'=>$role]);$id=(int)$pdo->lastInsertId();$p=$pdo->prepare('INSERT INTO user_profiles(user_id,full_name) VALUES(:id,:n)');$p->execute(['id'=>$id,'n'=>$fullName]);$pdo->commit();$success='Pengguna berhasil dibuat.';}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error='Pengguna gagal dibuat. Username mungkin sudah dipakai.';}}}
$rows=$pdo->query('SELECT u.id,u.username,u.role,u.created_at,up.full_name FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id ORDER BY u.id')->fetchAll();
require __DIR__ . '/../views/header.php';?>
<div class="page-head"><div><h1>Pengguna</h1><p class="sub">Halaman administrasi hanya dapat diakses oleh admin.</p></div></div>
<?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert"><?= e($success) ?></div><?php endif; ?>
<section class="panel"><h2>Tambah Pengguna</h2><form method="post" class="form-grid"><div class="field"><label>Nama lengkap</label><input name="full_name" required></div><div class="field"><label>Username</label><input name="username" required minlength="3"></div><div class="field"><label>Password (min. 8 karakter)</label><input type="password" name="password" required minlength="8"></div><div class="field"><label>Role</label><select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select></div><div class="field" style="justify-content:end"><button class="btn">Buat Pengguna</button></div></form></section>
<div class="table-wrap"><table><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Dibuat</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['full_name']) ?></td><td><?= e($r['username']) ?></td><td><?= e($r['role']) ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php require __DIR__ . '/../views/footer.php'; ?>
